use ea_crypto::{
    GRANT_SUITE_ID, SUITE_ID, SuiteV1, authorized_trust_digest, bootstrap_anchor_hash,
    ciphertext_digest, entry_hash, grant_digest, grant_plan_digest, hpke_aad, hpke_info,
    object_hash, operator_profile_digest, payload_aad, receipt_digest, record_digest,
    renewal_input_digest, trust_anchor_hash, trust_digest,
};
use ea_types::Hash32;

// Expected bytes were independently derived with a standalone RFC 8949 encoder,
// SHA-256 implementation, and RFC 8032 reference arithmetic. Production code
// did not generate any expected context, preimage, digest, AAD, info, or HPKE AAD.

#[derive(Clone, Copy)]
enum DigestConstruction {
    Ciphertext,
    Record,
    Object,
    GrantPlan,
    Grant,
    Receipt,
    Trust,
    AuthorizedTrust,
    RenewalInput,
    AnchorPre,
    AnchorFinal,
    OperatorProfile,
}

impl DigestConstruction {
    fn domain(self) -> &'static [u8] {
        match self {
            Self::Ciphertext => b"EINSATZARCHIV-CIPHERTEXT-v1",
            Self::Record => b"EINSATZARCHIV-RECORD-v1",
            Self::Object => b"EINSATZARCHIV-OBJECT-v1",
            Self::GrantPlan => b"EINSATZARCHIV-GRANT-PLAN-v1",
            Self::Grant => b"EINSATZARCHIV-GRANT-v1",
            Self::Receipt => b"EINSATZARCHIV-RECEIPT-v1",
            Self::Trust => b"EINSATZARCHIV-TRUST-OBJECT-v1",
            Self::AuthorizedTrust => b"EINSATZARCHIV-ADMIN-AUTHORIZED-TRUST-v1",
            Self::RenewalInput => b"EINSATZARCHIV-EVIDENCE-RENEWAL-INPUT-v1",
            Self::AnchorPre => b"EINSATZARCHIV-TRUST-ANCHOR-PRE-v1",
            Self::AnchorFinal => b"EINSATZARCHIV-TRUST-ANCHOR-v1",
            Self::OperatorProfile => b"EINSATZARCHIV-OPERATOR-PROFILE-v1",
        }
    }

    fn digest(self, context: &[u8]) -> [u8; 32] {
        match self {
            Self::Ciphertext => *ciphertext_digest(context).as_bytes(),
            Self::Record => *record_digest(context).as_bytes(),
            Self::Object => *object_hash(context).as_bytes(),
            Self::GrantPlan => *grant_plan_digest(context).as_bytes(),
            Self::Grant => *grant_digest(context).as_bytes(),
            Self::Receipt => *receipt_digest(context).as_bytes(),
            Self::Trust => *trust_digest(context).as_bytes(),
            Self::AuthorizedTrust => *authorized_trust_digest(context).as_bytes(),
            Self::RenewalInput => *renewal_input_digest(context).as_bytes(),
            Self::AnchorPre => *bootstrap_anchor_hash(context).as_bytes(),
            Self::AnchorFinal => *trust_anchor_hash(context).as_bytes(),
            Self::OperatorProfile => *operator_profile_digest(context).as_bytes(),
        }
    }
}

struct DigestKat {
    label: &'static str,
    construction: DigestConstruction,
    context_hex: &'static str,
    preimage_hex: &'static str,
    sha256_hex: &'static str,
    mutation_index: usize,
}

