    for kat in &digest_kats {
        let mut context = hex::decode(kat.context_hex).unwrap();
        let original = kat.construction.digest(&context);
        context[kat.mutation_index] ^= 1;
        assert_ne!(
            kat.construction.digest(&context),
            original,
            "{} ignored its construction-specific field mutation at byte {}",
            kat.label,
            kat.mutation_index
        );
    }

    let mut package_context = hex::decode("").unwrap();
    let package_record_digest = Hash32::try_from(&package_context[..32]).unwrap();
    let original_package = entry_hash(package_record_digest, &package_context[32..]);
    package_context[290] ^= 1;
    assert_ne!(
        entry_hash(package_record_digest, &package_context[32..]).as_bytes(),
        original_package.as_bytes(),
        "package digest ignored its Ed25519 signature-byte mutation"
    );

    let mut payload_aad_manifest_core_context = hex::decode("").unwrap();
    let payload_aad_manifest_core_original = payload_aad(&payload_aad_manifest_core_context);
    payload_aad_manifest_core_context[178] ^= 1;
    assert_ne!(
        payload_aad(&payload_aad_manifest_core_context),
        payload_aad_manifest_core_original,
        "payload_aad_manifest_core ignored its construction-specific field mutation"
    );

    let mut hpke_info_grant_context_context = hex::decode("").unwrap();
    let hpke_info_grant_context_original = hpke_info(&hpke_info_grant_context_context);
    hpke_info_grant_context_context[139] ^= 1;
    assert_ne!(
        hpke_info(&hpke_info_grant_context_context),
        hpke_info_grant_context_original,
        "hpke_info_grant_context ignored its construction-specific field mutation"
    );

    let mut hpke_aad_grant_context_context = hex::decode("").unwrap();
    let hpke_aad_grant_context_original = hpke_aad(&hpke_aad_grant_context_context);
    hpke_aad_grant_context_context[207] ^= 1;
    assert_ne!(
        hpke_aad(&hpke_aad_grant_context_context),
        hpke_aad_grant_context_original,
        "hpke_aad_grant_context ignored its construction-specific field mutation"
    );
